import json,re,shutil,hashlib
from pathlib import Path
W=Path(__file__).parent;G=W/'dist/bilder-optional';A=G/'assets';rows=json.load(open(W/'review.json'))
reuse={'HIS-0005':'GEO-0009','SCI-0013':'SCI-0011','TEC-0006':'HIS-0011'}
for dst,src in reuse.items():
 if (A/(src+'.jpg')).exists():shutil.copyfile(A/(src+'.jpg'),A/(dst+'.jpg'))
items=[]
for r in rows:
 id=r['id'];ext='svg' if id in ['GEO-0005','GEO-0006','GEO-0011','GEO-0016','GEO-0019','GEO-0022'] else 'jpg';has=r['verdict']!='Ohne Bild'
 p=2 if re.search('zwei (Nachkomma|Dezimal)',r['question'],re.I) else 1 if re.search('eine[rm]? (Nachkomma|Dezimal)',r['question'],re.I) else None
 items.append({k:r[k] for k in ['id','title','question','category','unit','verdict','note']}|{'precision':p,'image':'assets/'+id+'.'+ext if has else None,'alt':r['title']+' – Bildentwurf ohne Lösungsangabe' if has else '', 'kind':('Karte · Natural Earth' if ext=='svg' else 'Vorhandenes Giraffenporträt' if id=='SCI-0015' else 'KI-Motivstudie') if has else 'Bewusst ohne Bild'})
(G/'vorschau.json').write_text(json.dumps(items,ensure_ascii=False,indent=2)+'\n')
old=(W/'dist/bilder-vorschau/index.html').read_text();css=old.split('<style>')[1].split('</style>')[0]
css+='\n.filters{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:15px}.filters button{font-size:.875rem;padding:.45rem .8rem;min-height:42px}.filters button[aria-pressed=true]{border-color:var(--gold);color:var(--gold)}.intro{font-size:.95rem;color:var(--muted);line-height:1.55;margin:0 0 18px}.verdict{padding:12px 20px;border-bottom:1px solid var(--edge);font-weight:650;color:#a4d7cd}.verdict[data-value="Bei Bedarf"]{color:var(--gold)}.verdict[data-value="Ohne Bild"]{color:#f2b5a0}.placeholder{padding:24px;max-width:700px;text-align:center;color:var(--muted);line-height:1.6}.placeholder strong{display:block;font-size:1.25rem;color:#eef3f8;margin-bottom:12px}.note-visible{padding:15px 20px;margin:0;font-size:.95rem;line-height:1.55;color:#bccbd8;border-top:1px solid var(--edge)}.only-images .note-visible{display:none}.links{display:flex;gap:15px;flex-wrap:wrap}.links a{color:#b7d9de;font-size:.875rem}option{color:#eef3f8;background:#182638}header .brand small{font-size:.875rem}footer{font-size:.875rem}@media(max-width:560px){.caption,.game-link{font-size:.875rem}.image-box{min-height:200px}.placeholder{font-size:.95rem;padding:18px}.toolbar{flex-wrap:wrap}select{max-width:100%;flex:1;min-width:175px}.note-visible{padding:13px 16px}}'
html='''<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark"><title>Crosspoke – optionale Bilder</title><meta name="description" content="38 optionale Bildkandidaten im Vergleich: 31 Frage-Bild-Entwürfe und sieben begründete Auslassungen."><style>__CSS__</style></head><body><div class="shell"><header><a class="brand" href="#">♠ CROSSPOKE<small>Optionale Bilder · 38 geprüft</small></a><a class="game-link" href="https://crosspoke-test.do-peter.chatgpt.site/">Zum Spiel</a></header><p class="intro">19 sinnvolle Bildideen · 12 nur bei Bedarf · 7 besser ohne Bild.<br>31 Frage-Bild-Entwürfe zur Durchsicht. Noch nicht ins Spiel übernommen.</p><div class="filters" role="group" aria-label="Prüfergebnis filtern"><button data-filter="Alle" aria-pressed="true">Alle 38</button><button data-filter="Sinnvoll" aria-pressed="false">Sinnvoll · 19</button><button data-filter="Bei Bedarf" aria-pressed="false">Bei Bedarf · 12</button><button data-filter="Ohne Bild" aria-pressed="false">Ohne Bild · 7</button></div><div class="toolbar"><select id="jump" aria-label="Frage auswählen"></select><button class="mode" id="mode" aria-pressed="false">Nur Bilder</button></div><main><article class="card" aria-live="polite"><div class="verdict" id="verdict"></div><div class="question"><div class="eyebrow" id="category"></div><h1 id="question"></h1><div class="unit" id="unit"></div></div><figure class="image-box" id="swipe"><img id="picture" alt="" width="1200" height="800" draggable="false"><div class="placeholder" id="placeholder" hidden><strong>Hier empfehle ich kein Bild.</strong><span id="reason"></span></div></figure><div class="caption"><strong id="title"></strong><span id="kind"></span></div><p class="note-visible" id="note"></p><div id="error" class="error" hidden>Das Bild konnte nicht geladen werden. Die Frage bleibt über die Auswahl erreichbar.</div></article><nav class="navigation" aria-label="Bildnavigation"><button id="previous">Zurück</button><span class="counter" id="counter" aria-live="polite"></span><button class="primary" id="next">Weiter</button></nav><div class="progress" aria-hidden="true"><span id="bar"></span></div><details class="review"><summary>Prüfung und Herkunft</summary><p>Alle 38 Kandidaten wurden mit Frage, Einheit und beiden Hinweisen nach Q45–Q50 bewertet. Hinweise und Lösungen werden hier nicht angezeigt. Die Empfehlungen sind redaktionelle Einschätzungen, keine Playtestergebnisse.</p><p>KI-generierte Illustrationen sind erkennbare Motivstudien, keine Produktfotos oder historischen Belege. Modell-, Architektur- und Prägungsdetails sind vor einer Spielaufnahme gesondert abzugleichen. Karten: <a href="https://www.naturalearthdata.com/about/terms-of-use/" target="_blank" rel="noopener">Natural Earth · Public Domain</a>, ohne Maßstäbe, Staatsgrenzen oder Zeitzonen. Giraffenporträt aus der bereits freigegebenen Vorschau wiederverwendet.</p><p>38 optionale Kandidaten aus den spielbaren Zusatzfragen. Die ursprüngliche Titanic-Frage und die zurückgestellte Papierboot-Idee gehören nicht zu diesem Paket.</p></details><p class="links"><a href="https://crosspoke-test.do-peter.chatgpt.site/bilder-vorschau/">Die bisherigen 20 Bilder ansehen</a><a href="./vorschau.json" download>Vorschaudaten herunterladen</a></p></main><footer>Am Handy durch Wischen wechseln, am Computer mit den Pfeiltasten.<br>Fragenstand v0.9 · Spiel v0.2.4 mit 186 Fragen und 20 eingebauten Bildern bleibt erhalten.</footer></div><script>
const ITEMS=__ITEMS__;
const el=id=>document.getElementById(id);let filtered=ITEMS,current=0,filter='Alle',startX=null;
function options(){el('jump').replaceChildren();for(const [i,q] of filtered.entries()){const o=document.createElement('option');o.value=String(i);o.textContent=q.id+' · '+q.title;el('jump').append(o)}}
function show(i){current=Math.max(0,Math.min(filtered.length-1,i));const q=filtered[current];el('category').textContent=q.category+' · '+q.id;el('question').textContent=q.question;el('unit').textContent='Gesuchte Einheit: '+q.unit+(q.precision===1?' · 1 Nachkommastelle':q.precision===2?' · 2 Nachkommastellen':'');el('verdict').textContent=q.verdict==='Sinnvoll'?'Bildidee sinnvoll':q.verdict==='Bei Bedarf'?'Bild nur bei Bedarf':'Empfehlung: ohne Bild';el('verdict').dataset.value=q.verdict;el('picture').hidden=!q.image;el('placeholder').hidden=!!q.image;el('picture').alt=q.alt;if(q.image)el('picture').src=q.image;else el('picture').removeAttribute('src');el('reason').textContent=q.note;el('title').textContent=q.title;el('kind').textContent=q.kind;el('note').textContent=q.note;el('note').hidden=!q.image;el('counter').textContent=`${current+1} / ${filtered.length}`;el('jump').value=String(current);el('previous').disabled=current===0;el('next').disabled=current===filtered.length-1;el('bar').style.width=((current+1)/filtered.length*100)+'%';el('error').hidden=true;history.replaceState(null,'','#'+q.id);if(filtered[current+1]?.image){const p=new Image();p.src=filtered[current+1].image}}
el('picture').addEventListener('error',()=>{if(filtered[current].image)el('error').hidden=false});el('previous').addEventListener('click',()=>show(current-1));el('next').addEventListener('click',()=>show(current+1));el('jump').addEventListener('change',e=>show(Number(e.target.value)));el('mode').addEventListener('click',()=>{const only=document.body.classList.toggle('only-images');el('mode').setAttribute('aria-pressed',String(only));el('mode').textContent=only?'Frage & Bild':'Nur Bilder'});document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{const id=filtered[current].id;filter=b.dataset.filter;filtered=ITEMS.filter(q=>filter==='Alle'||q.verdict===filter);document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));options();show(Math.max(0,filtered.findIndex(q=>q.id===id)))}));document.addEventListener('keydown',e=>{if(['SELECT','INPUT','TEXTAREA'].includes(e.target.tagName))return;if(e.key==='ArrowLeft'){e.preventDefault();show(current-1)}if(e.key==='ArrowRight'){e.preventDefault();show(current+1)}});el('swipe').addEventListener('pointerdown',e=>startX=e.clientX);el('swipe').addEventListener('pointerup',e=>{if(startX===null)return;const dx=e.clientX-startX;startX=null;if(Math.abs(dx)>60)show(current+(dx<0?1:-1))});el('swipe').addEventListener('pointercancel',()=>startX=null);options();show(Math.max(0,ITEMS.findIndex(q=>q.id===location.hash.slice(1))));
</script></body></html>'''.replace('__CSS__',css).replace('__ITEMS__',json.dumps(items,ensure_ascii=False))
(G/'index.html').write_text(html)
(G/'README.txt').write_text('Crosspoke: 38 optionale Bildkandidaten. index.html öffnen. 31 Entwürfe, sieben begründete Auslassungen. 19 sinnvoll/12 bei Bedarf/7 ohne Bild. Keine aktiven Spieländerungen. Die beigefügten KI-Motive sind Studien; Details vor Einbau prüfen. Karten: Natural Earth, Public Domain.\n')
manifest=[{'path':str(p.relative_to(G)),'sha256':hashlib.sha256(p.read_bytes()).hexdigest()} for p in sorted(A.iterdir())]
(G/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
print('38 preview cards; assets currently:',len(manifest),'expected 31 after all generations arrive')
